let width = 30
var lines = [[String]](), current = [String](), letters = 0
for raw in paragraph.split(separator: " ") {
    let word = String(raw)
    if !current.isEmpty && letters + current.count + word.count > width {
        lines.append(current)
        current = []
        letters = 0
    }
    current.append(word)
    letters += word.count
}
if !current.isEmpty { lines.append(current) }
for (i, words) in lines.enumerated() {
    var text = ""
    if i == lines.count - 1 || words.count == 1 {
        text = words.joined(separator: " ").padding(toLength: width, withPad: " ", startingAt: 0)
    } else {
        let spaces = width - words.reduce(0) { $0 + $1.count }, gaps = words.count - 1
        text = words[0]
        for j in 1..<words.count {
            text += String(repeating: " ", count: spaces / gaps + (j - 1 < spaces % gaps ? 1 : 0))
            text += words[j]
        }
    }
    print("|\(text)|")
